'use strict';
// Product prototype: records and editable fictional details stay in memory only.
const C_bookings=[],C_cases=[];
let C_active=null,C_editing=null,C_draft=null,C_view='booker',C_error='',C_errorField='',C_case=null,C_submitting=false;
const C_originalHome=home,C_originalHead=head,C_originalModal=modal;
const C_clone=x=>JSON.parse(JSON.stringify(x));
const C_escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const C_booking=()=>C_bookings.find(b=>b.id===C_active);
const C_price=d=>d.service==='video'?300:(doctors.find(p=>p.id===d.provider)?.fee||0);
const C_defaults=()=>({who:'family',relation:'mother',country:'us',area:'lotus',service:'home',provider:0,day:availableDays()[0],slot:null,bookerName:'',bookerPhone:'',recipientName:'',recipientPhone:'',street:'',building:'',floor:'',access:'',contactMode:'recipient',contactName:'',contactPhone:'',adult:false,suitable:false,agreement:false,updates:false,ack:false,consentMethod:'recipient',consentState:'pending',contactVerified:false});
Object.assign(form,C_defaults());
function C_with(data,fn){const old=C_clone(form);Object.assign(form,data);try{return fn();}finally{Object.assign(form,old);}}
function C_saveDraft(){C_draft={data:C_clone(form),step,editingId:C_editing};if(C_editing){const b=C_bookings.find(x=>x.id===C_editing);if(b&&(!b.change||b.change.state==='draft'))b.change={state:'draft',data:C_clone(form)};}}
function C_name(){return C_escape(form.who==='self'?form.bookerName:form.recipientName)||T('Recipient','اللي هيستقبل الزيارة');}
recipient=function(){return C_name();};
address=function(){return C_escape([form.street,form.building].filter(Boolean).join(' · '))||T('North Lotus · example area','اللوتس الشمالية · نطاق تجريبي');};
function C_bilingual(fn){const old=lang;lang='en';const en=fn();lang='ar';const ar=fn();lang=old;return {en,ar};}
function C_stamp(){return new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{timeZone:'Africa/Cairo',hour:'2-digit',minute:'2-digit'}).format(new Date());}
function C_event(b,en,ar){b.events.push({en,ar,time:C_stamp()});}
function C_snapshot(d){return C_with(d,()=>`${C_name()} · ${timeLabel()} · ${money(C_price(d))}`);}

function C_digits(value){return String(value||'').replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c)));}
function C_phone(value,egypt=false){const v=C_digits(value).trim();if(!/^\+?[0-9 ()-]+$/.test(v))return false;const n=v.replace(/\D/g,'');if(egypt)return /^(?:20|0020)?1[0125][0-9]{8}$/.test(n)||/^01[0125][0-9]{8}$/.test(n);return /^\+/.test(v)?/^[1-9][0-9]{7,14}$/.test(n):/^00[1-9][0-9]{7,14}$/.test(n);}
function C_clearError(key){if(key&&C_errorField&&key!==C_errorField)return;C_error='';C_errorField='';document.getElementById('flowError')?.remove();document.querySelectorAll('[aria-invalid="true"]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');});document.querySelectorAll('.field-error').forEach(el=>el.remove());}
function C_clock(date,zone='Africa/Cairo'){return new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{timeZone:zone,hour:'numeric',minute:'2-digit',hour12:true}).format(date);}
function C_slot(i,zone='Africa/Cairo'){return C_with({...form,slot:i},()=>{const start=serviceDate();return C_clock(start,zone)+(form.service==='home'?' – '+C_clock(new Date(+start+3600000),zone):'');});}
timeLabel=function(zone='Africa/Cairo'){const date=new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{timeZone:zone,weekday:'short',day:'numeric',month:'short'}).format(serviceDate());return date+' · '+C_slot(form.slot,zone);};
windowLabel=function(){return form.service==='video'?T('Video starts at the selected time · Egypt time','الفيديو يبدأ في المعاد المحدد · بتوقيت مصر'):T('Arrival window · Egypt time · not consultation length','فترة وصول الدكتور · بتوقيت مصر · مش مدة الكشف');};

function C_field(key,label,opts={}){return `<label class="field" for="${key}">${label}<input id="${key}" name="${key}" data-field="${key}" value="${C_escape(form[key])}" ${opts.required?'required':''} ${opts.type?'type="'+opts.type+'"':'type="text"'} ${opts.phone?'inputmode="tel" dir="ltr"':''} ${C_errorField===key?'aria-invalid="true" aria-describedby="error-'+key+'"':''} autocomplete="off" maxlength="${opts.max||80}" placeholder="${C_escape(opts.placeholder||'')}" ${opts.required?'aria-required="true"':''}>${opts.hint?'<small>'+opts.hint+'</small>':''}${C_errorField===key?'<small class="field-error" id="error-'+key+'">'+C_error+'</small>':''}</label>`;}
function C_check(key,label,small=''){return `<label class="check"><input type="checkbox" data-field="${key}" id="${key}" ${form[key]?'checked':''}><span>${label}${small?'<small>'+small+'</small>':''}</span></label>`;}
function C_sampleButton(){return button(T('Fill with example details','استخدم بيانات المثال'),'data-sample','sample-button');}
head=function(){return C_originalHead().replace(T('Interactive concept · Not a live service · Use fictional details only','تجربة تفاعلية · مش خدمة شغّالة · استخدم بيانات المثال بس'),T('Interactive prototype · Fictional details only · No real booking or payment','نسخة تجريبية · بيانات غير حقيقية فقط · مفيش حجز أو دفع فعلي')).replace('<div class="actions">','<div class="actions">'+button(T('Menu','القائمة'),'data-modal="menu" aria-label="'+T('Open menu','افتح القائمة')+'"','mobile-menu'));};
home=function(){const el=document.createElement('template');el.innerHTML=C_originalHome();const hero=el.content.querySelector('.hero-copy');hero.querySelector('[data-start="family"]').textContent=T('Arrange a visit for someone I love','رتّب زيارة لحد بتحبّه');hero.querySelector('[data-start="self"]').textContent=T('A visit for me','زيارة ليا');hero.querySelector('small').innerHTML='<span class="pilot-label">'+icon('pin')+T('Proposed first area: North Lotus, Fifth Settlement.','أول نطاق مقترح: اللوتس الشمالية، التجمع الخامس.')+'</span><br>'+T('Explore the demo. Actual booking is not open yet.','جرّب الخطوات. الحجز الفعلي لسه مش متاح.');const grid=el.content.querySelector('.service-grid');grid.className='launch-services';grid.innerHTML=`<article class="launch-main"><div>${icon('home')}<span class="eyebrow">${T('Our first service · in preparation','أول خدمة · بنجهّزها')}</span><h3>${T('A doctor visit,<br>around their day.','دكتور ييجي لحد البيت.<br>في معاد يناسبهم.')}</h3><p>${T('Scheduled adult home consultations in one proposed local area. Choose who needs care, the address, the professional and a suitable arrival window.','كشف منزلي للكبار بميعاد، في نطاق محلي مقترح. اختار مين محتاج الزيارة، والعنوان والدكتور وفترة الوصول المناسبة.')}</p><div class="story-chips"><span class="pill">${T('Adult consultations','كشف للكبار')}</span><span class="pill">${T('Non-emergency','حالات غير طارئة')}</span></div>${button(T('Explore a home visit','شوف خطوات الزيارة'),'data-start="family"')}</div><div class="visit-orbit" aria-hidden="true"><div class="orbit-ring"></div><div class="orbit-home">${icon('home')}</div><span class="orbit-tag one">${icon('person')}${T('Your parent','والدك أو والدتك')}</span><span class="orbit-tag two">${icon('pin')}${T('Their address','عنوانهم')}</span><span class="orbit-tag three">${icon('clock')}${T('A suitable window','فترة مناسبة')}</span></div></article><article class="launch-video">${icon('video')}<span class="badge">${T('Second priority · preview','الخطوة التانية · تصوّر')}</span><h3>${T('Video, when it fits.','استشارة فيديو، لو مناسبة لحالتك.')}</h3><p>${T('A separate, professionally reviewed service. Recipient location, consent and connection recovery all matter.','خدمة منفصلة بمراجعة المختص. مكان اللي هيستقبلها وموافقته والتعامل مع انقطاع الاتصال، كلهم مهمين.')}</p>${button(T('Explore video care','اعرف عن الفيديو'),'data-go="video"','')}</article><details class="future-services"><summary>${T('What may come later: veterinary, nursing, diagnostics and pharmacy','خدمات ممكن نضيفها بعد كده: بيطري وتمريض وتحاليل وصيدلية')}</summary><p>${T('Each service needs qualified capacity, its own operating checks and accepted partners before it can be booked.','كل خدمة محتاجة مقدمين مؤهلين وتجهيزات تشغيل وشركاء معتمدين قبل إتاحة الحجز.')}</p><div class="story-chips">${[['vet','vet',T('Veterinary','بيطري')],['nurse','nurse',T('Nursing','تمريض')],['lab','lab',T('Diagnostics','تحاليل')],['pharmacy','pharmacy',T('Pharmacy','صيدلية')]].map(([r,i,n])=>button(icon(i)+n,`data-go="${r}"`,'')).join('')}</div></details>`;el.content.querySelector('.section-head p').textContent=T('We start with one service we can prepare properly. Additional categories follow their own readiness checks.','بنبدأ بخدمة واحدة نجهّزها كويس. وكل خدمة جديدة ليها شروط جاهزية منفصلة.');return el.innerHTML;};
rows=function(full=false){return `<div class="row"><span>${T('Care for','الزيارة لمين')}</span><b>${C_name()}</b></div><div class="row"><span>${T('Visit address','عنوان الزيارة')}</span><b>${address()}</b></div><div class="row"><span>${T('Service','الخدمة')}</span><b>${serviceName()}</b></div>${form.provider?`<div class="row"><span>${T('Professional','الدكتور')}</span><b>${lang==='ar'?provider().ar:provider().en}</b></div>`:''}${form.slot!==null&&(full||step>=3)?`<div class="row"><span>${T('Egypt time','بتوقيت مصر')}</span><b>${timeLabel()}<br>${windowLabel()}</b></div>${form.country==='us'?`<div class="row"><span>${T('New York time','بتوقيت نيويورك')}</span><b>${timeLabel('America/New_York')}</b></div>`:''}`:''}${form.provider?`<div class="row total"><span>${T('Example total','إجمالي المثال')}</span><b>${money(C_price(form))}</b></div>`:''}`;};
summary=function(){return `<aside class="panel summary"><h3>${T('Your visit, at a glance','ملخّص الزيارة')}</h3>${rows()}<div class="privacy-box">${icon('shield')}<span>${T('Example details stay in this browser tab. No service is ordered.','بيانات المثال بتفضل في التبويب ده. مفيش طلب خدمة فعلي.')}</span></div></aside>`;};
recipientStep=function(){return `<div class="choices compact-choices">${choice('family',form.who,T('Someone I care for','حد بهتم بيه'),T('A parent or adult relative','والدي، والدتي أو قريب بالغ'),'family','data-who')}${choice('self',form.who,T('Myself','لنفسي'),T('I will receive the visit','أنا اللي هستقبل الزيارة'),'person','data-who')}</div>${C_sampleButton()}<div class="field-grid">${C_field('bookerName',T('Your name','اسمك'),{required:true,placeholder:T('e.g. Omar Demo','مثال: عمر تجريبي')})}${C_field('bookerPhone',T('Your contact number','رقم للتواصل معاك'),{required:true,phone:true,placeholder:'+1 202 555 0146',hint:T('Outside Egypt? Include your country code. Egyptian mobile numbers can start with 01 or +20.','لو رقمك من برّه مصر، اكتب كود البلد. الرقم المصري ممكن يبدأ بـ01 أو +20.')})}</div>${form.who==='family'?`<label class="field">${T('Who are you arranging the visit for?','بترتّب الزيارة لمين؟')}<select id="relation" data-field="relation"><option value="mother" ${form.relation==='mother'?'selected':''}>${T('My mother','والدتي')}</option><option value="father" ${form.relation==='father'?'selected':''}>${T('My father','والدي')}</option><option value="relative" ${form.relation==='relative'?'selected':''}>${T('Another adult relative','قريب بالغ تاني')}</option></select></label><div class="field-grid">${C_field('recipientName',T('Their name','اسمه أو اسمها'),{required:true,placeholder:T('e.g. Mona Demo','مثال: منى تجريبية')})}${C_field('recipientPhone',T('Their contact number in Egypt','رقم التواصل معاه في مصر'),{required:true,phone:true,placeholder:'+20 10 0000 0000'})}</div>`:''}<label class="field">${T('Where are you arranging this from?','بترتّب الزيارة منين؟')}<select id="country" data-field="country"><option value="us" ${form.country==='us'?'selected':''}>${T('United States · New York time example','أمريكا · مثال بتوقيت نيويورك')}</option><option value="eg" ${form.country==='eg'?'selected':''}>${T('Egypt','مصر')}</option></select></label>${C_check('adult',T('The person receiving care is an adult.','اللي هيستقبل الرعاية شخص بالغ.'))}<details class="quiet-details"><summary>${T('Booking from abroad','الحجز من برّه مصر')}</summary><p>${T('We show New York and Egypt time in this example. International access, phone verification and cards still need testing before launch.','المثال بيعرض توقيت نيويورك ومصر. الدخول والتحقق من الأرقام والكروت من برّه مصر لسه محتاجين اختبار قبل التشغيل.')}</p></details>`;};
addressStep=function(){return `<label class="field">${T('Where will the visit happen?','الزيارة هتكون فين؟')}<select id="area" data-field="area"><option value="lotus" ${form.area==='lotus'?'selected':''}>${T('North Lotus · example area','اللوتس الشمالية · نطاق المثال')}</option><option value="boundary" ${form.area==='boundary'?'selected':''}>${T('Edge of Fifth Settlement · needs checking','طرف التجمع الخامس · محتاج مراجعة')}</option><option value="outside" ${form.area==='outside'?'selected':''}>${T('Outside the example area','برّه نطاق المثال')}</option></select></label>${form.area!=='lotus'?`<div class="error" role="status">${T('There are no supported example visits at this address. Choose North Lotus to continue the demo. We will not switch the recipient’s address or service without agreement.','مفيش زيارة متاحة في المثال على العنوان ده. اختار اللوتس الشمالية علشان تكمّل. مش هنغيّر عنوان الزيارة أو نوع الخدمة من غير موافقة.')}</div>${button(T('Ask about coverage','استفسر عن النطاق'),'data-modal="customer"','')}`:`${C_sampleButton()}${C_field('street',T('Street / neighbourhood detail','الشارع أو تفاصيل المنطقة'),{required:true,placeholder:T('Example Street','شارع تجريبي')})}<div class="field-grid">${C_field('building',T('Building / unit','العمارة أو الوحدة'),{required:true,placeholder:T('Building A · apartment 2','عمارة أ · شقة ٢')})}${C_field('floor',T('Floor · optional','الدور · اختياري'),{placeholder:T('Second floor','الدور التاني')})}</div>${C_field('access',T('Access details · optional','تفاصيل الوصول · اختياري'),{placeholder:T('Lift, entrance or meeting point','أسانسير أو مدخل أو نقطة مقابلة'),max:160})}<label class="field">${T('Who can help with arrival?','مين يقدر يساعد وقت الوصول؟')}<select id="contactMode" data-field="contactMode"><option value="recipient" ${form.contactMode==='recipient'?'selected':''}>${T('The person receiving the visit','اللي هيستقبل الزيارة')}</option><option value="other" ${form.contactMode==='other'?'selected':''}>${T('Another trusted local contact','حد موثوق موجود قريب منه')}</option></select></label>${form.contactMode==='other'?`<div class="field-grid">${C_field('contactName',T('Local contact’s name','اسم الشخص القريب'),{required:true})}${C_field('contactPhone',T('Their Egypt contact number','رقمه في مصر'),{required:true,phone:true})}</div>`:''}<div class="note short-note">${T('The recipient’s address determines coverage. Your location and card country do not.','نطاق الخدمة بيتحدد بعنوان اللي هيستقبلها، مش بمكانك أو بلد الكارت.')}</div>`}`;};
serviceStep=function(){return `<div class="choices compact-choices">${choice('home',form.service,T('Doctor at home','دكتور في البيت'),T('First proposed service','أول خدمة مقترحة'),'home','data-service')}${choice('video',form.service,T('Video consultation','استشارة فيديو'),T('Later release · preview','تشغيل لاحق · تصوّر'),'video','data-service')}</div><div class="scope-card">${icon(form.service==='home'?'home':'video')}<div><b>${form.service==='home'?T('Scheduled adult consultations','كشف للكبار بميعاد'):T('An appropriate remote consultation','استشارة مناسبة عن بُعد')}</b><p>${form.service==='home'?T('A qualified professional reviews whether the requested care can be delivered safely at home. Medicines, tests and nursing are not included automatically.','المختص بيراجع إذا كانت الخدمة ينفع تتقدّم في البيت بأمان. الأدوية والتحاليل والتمريض مش ضمن الزيارة تلقائيًا.'):T('A professional must approve suitability. The recipient must be physically in the approved Egypt scope. No real video call is started here.','المختص لازم يوافق على مناسبة الفيديو. الشخص اللي هيستقبل الاستشارة لازم يكون موجود فعليًا في النطاق المعتمد في مصر. مفيش مكالمة فعلية هنا.')}</p></div></div>${C_check('suitable',T('This example is a planned, non-emergency adult consultation.','المثال ده لكشف لشخص بالغ، بميعاد ولحالة غير طارئة.'),T('This checkbox is not a clinical assessment. Actual suitability needs professional review.','الاختيار ده مش تقييم طبي. مناسبة الحالة لازم يراجعها مختص.'))}<div class="note warning short-note">${T('For an emergency, seek local emergency care. Do not wait for a visit or support reply.','في الطوارئ، اطلب رعاية طارئة محلية. متستناش زيارة أو رد من الدعم.')}</div>${button(T('Help choosing the right route','مساعدة في اختيار المسار المناسب'),'data-modal="support"','text-btn')}`;};
providerStep=function(){return `<div class="provider-list">${doctors.map(d=>`<article class="provider ${form.provider===d.id?'selected':''}"><div class="provider-top"><div class="avatar" aria-hidden="true">${d.initials}</div><div><h3>${lang==='ar'?d.ar:d.en}</h3><small>${lang==='ar'?d.spec[1]:d.spec[0]} · ${T('Fictional profile','بروفايل تجريبي')}</small></div><b class="provider-price">${money(form.service==='video'?300:d.fee)}</b></div><details class="quiet-details"><summary>${T('Professional information and scope','التفاصيل المهنية ونطاق الخدمة')}</summary><p>${T('A suitable adult consultation, subject to professional review. Registration, credentials, visit content and actual availability must be verified before launch. No real review score or verified badge is shown.','كشف مناسب لشخص بالغ، بعد مراجعة المختص. التسجيل والمؤهلات وتفاصيل الزيارة والمواعيد لازم يتراجعوا قبل التشغيل. مفيش تقييم أو علامة توثيق حقيقية في المثال.')}</p></details>${button(form.provider===d.id?T('Chosen','اختيارك'):T('Choose','اختار'),`data-provider="${d.id}"`,form.provider===d.id?'dark':'')}</article>`).join('')}</div><div class="date-section"><label class="field">${T('Choose a date','اختار يوم')}<input type="date" id="visitDate" value="${dateISO(form.day)}" min="${dateISO(1)}" max="${dateISO(14)}"></label><div class="slots" aria-label="${T('Example available days','أيام متاحة في المثال')}">${availableDays().map(n=>`<button data-day="${n}" aria-pressed="${form.day===n}">${new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{timeZone:'Africa/Cairo',weekday:'short',day:'numeric',month:'short'}).format(new Date(dateISO(n)+'T12:00:00Z'))}</button>`).join('')}</div>${!availableDays().includes(form.day)?`<div class="error">${T('No sample availability on that date. Choose one of the days above.','مفيش مواعيد تجريبية في اليوم ده. اختار يوم من الأمثلة فوق.')}</div>`:''}<b>${form.service==='video'?T('Video start time · Egypt time','معاد بداية الفيديو · بتوقيت مصر'):T('Doctor arrival window · Egypt time','فترة وصول الدكتور · بتوقيت مصر')}</b><div class="slots">${[0,1].map(i=>`<button data-slot="${i}" aria-pressed="${form.slot===i}">${C_slot(i)}</button>`).join('')}</div><small>${form.service==='video'?T('Example appointments. This is the call start time, not an arrival window.','مواعيد للتجربة. ده معاد بداية المكالمة، مش فترة وصول.'):T('The doctor arrives within this window. It is not the consultation length. Example availability only.','الدكتور يوصل خلال الفترة دي، وهي مش مدة الكشف. المواعيد للتجربة بس.')}</small>${form.country==='us'&&form.slot!==null?`<div class="timezone-pair"><span>${T('Egypt','مصر')}<b>${timeLabel()}</b></span><span>${T('New York','نيويورك')}<b>${timeLabel('America/New_York')}</b></span></div>`:''}</div>`;};
permissionsStep=function(){return form.who==='self'?
 '<div class="scope-card">'+icon('person')+'<div><h3>'+T('Your visit. Your decision.','زيارتك. والقرار ليك.')+'</h3><p>'+T('No family invitation is needed. Check your contact and confirm your own visit.','مش محتاج دعوة لحد من أهلك. راجع رقمك وأكّد موافقتك على الزيارة.')+'</p></div></div>'+C_check('agreement',T('I agree to this example visit for myself.','موافق على الزيارة التجريبية لنفسي.')):
 '<div class="roles-strip"><span>'+T('Arranged by','بيرتّب الزيارة')+'<b>'+C_escape(form.bookerName)+'</b></span><span>'+T('Care for','الزيارة لـ')+'<b>'+C_name()+'</b></span></div><label class="field">'+T('How would they like to respond?','نأكد معاهم الزيارة إزاي؟')+'<select data-field="consentMethod" id="consentMethod"><option value="recipient" '+(form.consentMethod==='recipient'?'selected':'')+'>'+T('A private invitation to the recipient','دعوة خاصة للي هيستقبل الزيارة')+'</option><option value="assisted" '+(form.consentMethod==='assisted'?'selected':'')+'>'+T('Help by phone','مساعدة بمكالمة')+'</option><option value="representative" '+(form.consentMethod==='representative'?'selected':'')+'>'+T('An authorized representative','عن طريق شخص معاه تفويض مناسب')+'</option></select></label><section class="invitation-tracker"><span class="badge">'+T('Booker’s view · example','من جهة اللي بيحجز · تجربة')+'</span><h3>'+T('Their choice comes first.','موافقتهم هي البداية.')+'</h3><ol class="invitation-steps"><li class="done">'+T('Visit details ready','تفاصيل الزيارة جاهزة')+'</li><li class="'+(form.contactVerified?'done':'')+'">'+T('Contact checked','مراجعة رقم التواصل')+'</li><li class="'+(form.consentState==='approved'?'done':'')+'">'+T('Recipient response','رد اللي هيستقبل الزيارة')+'</li></ol><p role="status">'+(form.consentState==='approved'?T('Agreed. You can review the request together.','الموافقة اتسجلت. تقدر تراجع الطلب وتكمّل.'):form.consentState==='declined'?T('They have declined. No request will be sent.','الزيارة مش مناسبة لهم. مش هنبعت طلب للدكتور.'):T('Waiting for their decision. Nothing has been sent in this prototype.','لسه مستنيين قرارهم. مفيش رسالة اتبعتت في النسخة التجريبية.'))+'</p>'+button(form.consentMethod==='recipient'?T('Open recipient invitation','افتح دعوة الزيارة'):T('Preview assisted review','شوف خطوات المراجعة بمساعدة'),'data-invitation')+'</section>'+(form.consentState==='approved'?C_check('agreement',T('I understand their choice and the agreed coordination role.','فاهم اختيارهم وحدود دوري في ترتيب الزيارة.')):'')+'<details class="quiet-details"><summary>'+T('What can the booker see?','اللي بيحجز يقدر يشوف إيه؟')+'</summary><p>'+T('Your payment receipt stays available. The recipient chooses whether to share booking updates. Medical details need separate permission.','إيصال الدفع يفضل متاح ليك. اللي هيستقبل الزيارة هو اللي يختار مشاركة تحديثات الحجز. التفاصيل الطبية محتاجة إذن منفصل.')+'</p></details>';};

reviewStep=function(){const old=C_editing?C_bookings.find(b=>b.id===C_editing):null;return `${old?`<div class="note"><b>${T('Your original visit stays confirmed.','زيارتك الأصلية لسه مؤكدة.')}</b>${C_snapshot(old.data)}<br>${T('The proposed change replaces it only after acceptance and the required payment adjustment.','التغيير المقترح يستبدلها بعد القبول وتسوية فرق المبلغ المطلوبة بس.')}</div>`:''}${rows(true)}<div class="row"><span>${T('Travel in this example','المشوار في المثال')}</span><b>${form.service==='video'?T('Not applicable','مش مطلوب'):T('Included','ضمن السعر')}</b></div>${old?`<div class="row"><span>${T('Example price difference','فرق السعر في المثال')}</span><b>${money(C_price(form)-C_price(old.data))}</b></div>`:''}<div class="row"><span>${T('Updates to booker','تحديثات للي بيحجز')}</span><b>${form.who==='self'?T('Your own visit','زيارتك إنت'):form.updates?T('Booking status only','حالة الحجز بس'):T('Payment receipt only','إيصال الدفع بس')}</b></div><details class="quiet-details"><summary>${T('Fees, payment and changes','السعر والدفع والتغييرات')}</summary><p>${T('Prices are illustrative. No medicines, tests, nursing or procedures are included. The simulated flow holds a payment amount, then captures after acceptance. Actual fees, tax, cancellation and refund terms must be agreed before launch; this is not a free-cancellation promise.','الأسعار للتجربة. الأدوية والتحاليل والتمريض والإجراءات مش ضمنها. المسار التجريبي بيحجز مبلغ وبعد القبول بيحصّله. الأسعار والضرائب وشروط الإلغاء والاسترداد الفعلية لازم تتحدد قبل التشغيل، ومش بنوعد بإلغاء مجاني.')}</p></details>${C_check('ack',T('I understand this sends no real request and charges no money.','فاهم إن مفيش طلب فعلي هيتبعت ومفيش فلوس هتتخصم.'))}`;};
booking=function(){const names=[T('Who is the care for?','الزيارة لمين؟'),T('Their address comes first.','البداية من عنوان الزيارة.'),T('Choose a suitable service.','اختار الخدمة المناسبة.'),T('Choose who and when.','اختار الدكتور والمعاد اللي يناسبك.'),T('Agree how to coordinate.','نأكد التفاصيل معاهم.'),T('Review your visit.','راجع تفاصيل الزيارة.'),T('Follow your visit.','تابع زيارتك.')];return `<main id="main" class="booking-shell page-enter"><div class="booking-head">${button(T('← Back','ارجع →'),'data-back','back')}<span class="eyebrow">${C_editing?T('Change a visit','تغيير زيارة'):T('Arrange care','رتّب رعاية')} · ${T('Step','خطوة')} ${step+1}/7</span><h1 id="pageTitle" tabindex="-1">${step===6?C_statusLabel(C_booking()?.status):names[step]}</h1>${step<6?`<div class="progress" aria-label="${T('Booking progress','خطوات الحجز')}">${steps.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div>`:''}</div>${step>0&&step<5?`<details class="mobile-summary"><summary>${T('Your selections','اختياراتك')}</summary>${rows()}</details>`:''}<div class="booking-layout"><section class="panel">${C_error?`<div id="flowError" class="error" role="alert" tabindex="-1">${C_error}</div>`:''}<form id="familyStep" novalidate>${[recipientStep,addressStep,serviceStep,providerStep,permissionsStep,reviewStep,statusStep][step]()}${step<6?'<button type="submit" class="sr-only" tabindex="-1" aria-hidden="true">Continue</button>':''}</form></section>${step===6&&C_booking()?C_with(C_booking().data,summary):summary()}</div></main>${step<6?dock():''}`;};
dock=function(){const labels=[T('Continue','كمّل'),T('Choose care','اختار الخدمة'),T('Choose a doctor','اختار الدكتور'),T('Contact & agreement','التواصل والموافقة'),T('Review visit','راجع الزيارة'),C_editing?T('Request this change','اطلب التغيير'):T('Try sending the request','جرّب إرسال الطلب')];return `<div class="booking-dock"><div><b>${C_name()}</b><small>${form.provider?money(C_price(form)):T('Fictional details only','بيانات تجريبية بس')}</small></div>${button(labels[step],'data-next')}</div>`;};
function C_statusLabel(s){return ({pending:T('Awaiting acceptance','مستني قبول الدكتور'),accepted:T('Payment pending','الدفع لسه معلّق'),paymentfailed:T('Payment needs attention','الدفع محتاج مراجعة'),confirmed:T('Visit confirmed · demo','زيارة مؤكدة · تجربة'),complete:T('Visit completed · demo','الزيارة اكتملت · تجربة'),declined:T('Request not accepted','الطلب متقبلش'),expired:T('Request expired','مهلة الطلب انتهت'),cancelled:T('Visit cancelled · demo','الزيارة اتلغت · تجربة')})[s]||T('Visit details','تفاصيل الزيارة');}
const C_permissionBody=permissionsStep;
permissionsStep=function(){const number=form.who==='self'?form.bookerPhone:form.recipientPhone;return '<div class="contact-check"><div><b>'+(form.who==='self'?T('Check your contact number','راجع رقم التواصل معاك'):T('Check their contact number','راجع رقم التواصل معاهم'))+'</b><p dir="ltr">'+C_escape(number)+'</p></div>'+button(form.contactVerified?T('Example contact checked','التواصل اتراجع في المثال'):T('Try the contact check','جرّب مراجعة التواصل'),'data-verify-contact',form.contactVerified?'dark':'')+'<small>'+T('Demo only. No SMS is sent and no real identity is verified.','للتجربة بس. مفيش رسالة بتتبعت أو تحقق من هوية فعلية.')+'</small></div>'+C_permissionBody();};
function C_recordView(b){return C_with(b.data,()=>{const restricted=C_view==='booker'&&form.who==='family'&&!form.updates;return `<div class="record-title"><span class="badge">${b.id}</span><span class="pill">${C_statusLabel(b.status)}</span></div><div class="role-switch" role="group" aria-label="${T('Role preview, not authentication','تصوّر للأدوار، مش تسجيل دخول')}">${button(T('Booker view','تصوّر اللي بيحجز'),'data-role="booker" aria-pressed="'+(C_view==='booker')+'"','')}${button(T('Recipient view','تصوّر اللي هيستقبل الزيارة'),'data-role="recipient" aria-pressed="'+(C_view==='recipient')+'"','')}</div><small>${T('Both views are available only to demonstrate permissions. No real identity is authenticated.','التصورين متاحين علشان يوضحوا الصلاحيات بس. مفيش تحقق من هوية فعلية.')}</small>${b.change?C_changePanel(b):''}${rows(true)}${C_stateControls(b)}${restricted?`<div class="note">${T('The recipient did not permit ongoing visit updates to the booker in this example. The request details you entered and your payment receipt remain available.','الشخص موافقش في المثال على مشاركة تحديثات الزيارة مع اللي بيحجز. تفاصيل الطلب اللي دخلتها وإيصال دفعك لسه متاحين.')}</div>`:C_followThrough(b)}${C_view==='recipient'&&form.who==='family'?'<div class="note">'+T('The booker handles their payment receipt. Your medical details remain private; this view shares no clinical record.','إيصال الدفع عند اللي دفع. تفاصيلك الطبية ليها خصوصيتها؛ مفيش ملف طبي بيتشارك من الشاشة دي.')+'</div>':C_receipt(b)}<div class="status-actions">${['confirmed','pending','accepted','paymentfailed'].includes(b.status)?button(T('Change or cancel','غيّر أو الغي'),'data-modal="manage"',''):''}${button(T('Help with this visit','مساعدة في الزيارة'),'data-modal="support"','')}${button(T('All visits','كل الزيارات'),'data-go="care"','')}</div><details class="quiet-details"><summary>${T('Request history','سجل الطلب')}</summary><ol class="event-list">${b.events.map(e=>`<li><small>${e.time}</small> ${lang==='ar'?e.ar:e.en}</li>`).join('')}</ol></details>`;});}
statusStep=function(){const b=C_booking();return b?C_recordView(b):`<p>${T('Choose a visit from My care.','اختار زيارة من رعايتي.')}</p>`;};
function C_changePanel(b){const c=b.change;return `<div class="change-panel"><span class="badge">${T('Original visit stays confirmed','الزيارة الأصلية لسه مؤكدة')}</span><h3>${T('A change is being arranged.','في تغيير بنرتّب له.')}</h3><div class="change-comparison"><div><small>${T('Original · still confirmed','الأصلية · لسه مؤكدة')}</small><b>${C_snapshot(b.data)}</b></div><div><small>${T('Requested change','التغيير المطلوب')}</small><b>${C_snapshot(c.data)}</b></div></div><div class="row"><span>${T('Price difference','فرق السعر')}</span><b>${money(C_price(c.data)-C_price(b.data))}</b></div>${c.state==='draft'?button(T('Continue change draft','كمّل مسودة التغيير'),'data-resume-change'):c.state==='pending'?`<div class="status-actions">${button(T('Simulate change acceptance','جرّب قبول التغيير'),'data-change="accept"')}${button(T('Simulate decline','جرّب رفض التغيير'),'data-change="decline"','')}</div>`:`<p>${T('Accepted; example price adjustment still pending. The original remains in place until this completes.','التغيير اتقبل؛ تسوية فرق السعر في المثال لسه معلّقة. الزيارة الأصلية تفضل زي ما هي لحد ما الخطوة دي تكتمل.')}</p>${button(T('Simulate adjustment & replace visit','جرّب التسوية وتأكيد التغيير'),'data-change="confirm"')}`}<div>${button(T('Keep the original visit','خلّي الزيارة الأصلية'),'data-change="discard"','text-btn')}</div></div>`;}
function C_stateControls(b){if(b.change)return '';if(b.status==='pending')return `<div class="note"><b>${T('Request pending. No appointment is confirmed.','الطلب معلّق. لسه مفيش ميعاد مؤكد.')}</b>${T('The payment hold is an illustrative design, not a verified app capability.','حجز المبلغ تصوّر للتصميم، مش ميزة متحقق منها في التطبيق.')}</div><div class="status-actions">${button(T('Simulate acceptance','جرّب القبول'),'data-status="accepted"')}${button(T('Try rejection','جرّب الرفض'),'data-status="declined"','')}${button(T('Try no response','جرّب عدم الرد'),'data-status="expired"','')}</div>`;if(['accepted','paymentfailed'].includes(b.status))return `<div class="note warning"><b>${T('Not confirmed yet.','لسه مش مؤكد.')}</b>${T('Provider acceptance and completed payment are separate steps. No real charge is attempted here.','قبول الدكتور واكتمال الدفع خطوتين مختلفتين. مفيش محاولة خصم فعلي هنا.')}</div><div class="status-actions">${button(T('Simulate completed payment','جرّب اكتمال الدفع'),'data-status="confirmed"')}${button(T('Simulate payment failure','جرّب فشل الدفع'),'data-status="paymentfailed"','')}</div>`;if(['declined','expired'].includes(b.status))return `<div class="note">${T('The simulated payment hold is released. Choose another provider or time; no substitution happens automatically.','حجز المبلغ التجريبي اتفك. اختار دكتور أو معاد تاني؛ مفيش تبديل تلقائي.')}</div>${button(T('Create an alternative request','رتّب طلب بديل'),'data-retry')}`;return '';}
function C_followThrough(b){if(!['confirmed','complete'].includes(b.status))return '';const phase=b.visit||'scheduled';return `<section class="after-visit"><h3>${T('Before and during the visit','قبل الزيارة وأثناءها')}</h3><div class="visit-status">${icon(phase==='delayed'?'clock':phase==='arrived'?'home':'calendar')}<div><b>${({scheduled:T('Your example window is reserved','فترة الزيارة محجوزة في المثال'),travelling:T('Provider travelling · simulated','الدكتور في الطريق · تجربة'),delayed:T('A delay needs coordination','في تأخير محتاج تنسيق'),arrived:T('Provider arrived · simulated','الدكتور وصل · تجربة'),completed:T('Service recorded as complete · simulated','الخدمة اتسجلت مكتملة · تجربة')})[phase]}</b><p>${phase==='delayed'?T('Support should check the revised arrival window with the recipient. No new time is assumed without agreement.','الدعم يراجع فترة الوصول الجديدة مع الشخص. مفيش معاد جديد يتفرض من غير موافقة.'):T('No live GPS, reminder or message is sent.','مفيش تتبّع فعلي أو تذكير أو رسالة بتتبعت.')}</p></div></div><details class="quiet-details" open><summary>${form.service==='video'?T('Prepare to join','جهّز للدخول'):T('Prepare for the visit','جهّز للزيارة')}</summary><ul>${(form.service==='video'?[T('Use a private place and check the connection.','اختار مكان فيه خصوصية واتأكد من الاتصال.'),T('Recipient identity and physical location must be checked privately.','هوية الشخص ومكانه الفعلي لازم يتراجعوا بشكل خاص.'),T('Joining access is private; the payer does not automatically join.','الدخول خاص؛ اللي دفع مش بيدخل تلقائيًا.')]:[T('Confirm the address, entrance and available local contact.','اتأكد من العنوان والمدخل والشخص المتاح للتواصل.'),T('Know the professional’s identity before receiving the visit.','اعرف بيانات الدكتور قبل استقبال الزيارة.'),T('Prepare relevant documents privately; do not upload them here.','جهّز المستندات المطلوبة بشكل خاص؛ متحمّلهاش هنا.')]).map(x=>'<li>'+x+'</li>').join('')}</ul></details>${b.status==='confirmed'?`<details class="quiet-details"><summary>${T('Explore visit scenarios','جرّب مواقف أثناء الزيارة')}</summary><div class="status-actions">${button(T('Provider travelling','الدكتور في الطريق'),'data-visit="travelling"','')}${button(T('Delay','تأخير'),'data-visit="delayed"','')}${button(T('Arrival','وصول'),'data-visit="arrived"','')}${button(T('Recipient unreachable','الشخص مش بيرد'),'data-unreachable','')}${form.service==='video'?button(T('Joining / connection help','مساعدة في الدخول والاتصال'),'data-modal="video-room"',''):''}${button(T('Simulate service completion','جرّب اكتمال الخدمة'),'data-status="complete"')}</div></details>`:`<div class="note"><b>${T('Next steps stay private.','الخطوات الجاية ليها خصوصيتها.')}</b>${T('A real service would provide approved documentation through an authorized private route. No diagnosis, prescription or clinical result is generated here.','الخدمة الفعلية توفّر المستندات المعتمدة للمصرّح لهم بطريقة خاصة. مفيش تشخيص أو روشتة أو نتيجة طبية بتتعمل هنا.')}</div>`}</section>`;}
function C_receipt(b){return `<details class="receipt quiet-details" ${b.status==='cancelled'?'open':''}><summary>${T('Payment, receipt & refunds','الدفع والإيصال والاسترداد')}</summary><div class="row"><span>${T('Payer','اللي بيدفع')}</span><b>${C_escape(b.data.bookerName)}</b></div><div class="row"><span>${T('Example amount','مبلغ المثال')}</span><b>${money(C_price(b.data))}</b></div><div class="row"><span>${T('Payment state','حالة الدفع')}</span><b>${({hold:T('Simulated authorization only','حجز مبلغ تجريبي بس'),captured:T('Simulated payment complete','دفع مكتمل للتجربة'),released:T('Simulated hold released','حجز المبلغ التجريبي اتفك'),refundpending:T('Simulated refund pending','استرداد معلّق للتجربة'),refunded:T('Simulated refund complete','استرداد مكتمل للتجربة')})[b.payment]}</b></div>${b.payment==='refundpending'?`<p>${T('Actual cancellation fees and original-method refund timing require agreed terms. This demo does not promise a refund deadline or free cancellation.','رسوم الإلغاء ووقت الاسترداد لنفس وسيلة الدفع محتاجين شروط معتمدة. التجربة مش بتوعد بمهلة استرداد أو إلغاء مجاني.')}</p>${button(T('Simulate refund completion','جرّب اكتمال الاسترداد'),'data-refund','')}`:''}<small>${T('Not a tax invoice or a payment receipt for a real transaction.','مش فاتورة ضريبية أو إيصال لمعاملة فعلية.')}</small></details>`;}
care=function(){return `<main id="main" class="dashboard page-enter"><span class="eyebrow">${T('My care · this tab only','رعايتي · في التبويب ده بس')}</span><h1>${T('Every visit has its place.','كل زيارة ليها تفاصيلها.')}</h1><p>${T('Example visits stay separate from new drafts and proposed changes. Reloading clears this demonstration.','الزيارات التجريبية منفصلة عن المسودات والتغييرات المقترحة. تحديث الصفحة بيمسح التجربة.')}</p>${C_draft?`<section class="draft-card"><div>${icon('calendar')}<b>${C_draft.editingId?T('An unfinished change','تغيير لسه مكمّلش'):T('An unfinished visit','زيارة لسه مكمّلتش')}</b></div>${button(T('Continue draft','كمّل المسودة'),'data-resume','')}</section>`:''}<div class="care-ledger">${C_bookings.length?C_bookings.slice().reverse().map(b=>`<article class="panel"><div class="record-title"><span class="badge">${b.id}</span><span class="pill">${C_statusLabel(b.status)}</span></div><h2>${C_escape(b.data.who==='self'?b.data.bookerName:b.data.recipientName)}</h2><p>${C_snapshot(b.data)}</p>${b.change?'<div class="note short-note">'+T('Change in progress. The original remains confirmed.','في تغيير جاري. الزيارة الأصلية لسه مؤكدة.')+'</div>':''}${button(T('View visit','شوف الزيارة'),`data-open-booking="${b.id}"`,'')}</article>`).join(''):`<section class="panel"><h2>${T('Your first example visit starts here.','ابدأ بأول زيارة تجريبية.')}</h2><p>${T('Arrange care for yourself or someone you love.','رتّب زيارة ليك أو لحد من أهلك.')}</p></section>`}</div><div class="status-actions">${button(T('Arrange another visit','رتّب زيارة تانية'),'data-start="family"')}${button(T('Support cases','طلبات المساعدة'),'data-go="support-cases"','')}</div></main>`;};
function C_casePage(){const c=C_cases.find(x=>x.id===C_case);return `<main id="main" class="dashboard page-enter"><span class="eyebrow">${T('Support simulation · no message sent','تجربة للدعم · مفيش رسالة بتتبعت')}</span><h1>${T('Help, with a clear next step.','مساعدة، وخطوة جاية واضحة.')}</h1>${c?`<section class="panel"><div class="record-title"><span class="badge">${c.id}</span><span class="pill">${C_caseStatus(c.status)}</span></div><h2>${C_reason(c.reason)}</h2><div class="row"><span>${T('Queue','الفريق')}</span><b>${c.queue==='provider'?T('Provider / business support','دعم مقدمي الخدمة والأعمال'):c.reason==='payment'?T('Payment coordination','متابعة الدفع'):T('Customer / caregiver support','دعم العملاء وترتيب الرعاية')}</b></div><div class="row"><span>${T('Responsible role','الدور المسؤول')}</span><b>${c.queue==='provider'?T('Provider onboarding coordinator','مسؤول تفعيل مقدمي الخدمة'):c.reason==='payment'?T('Finance coordinator','مسؤول متابعة المالية'):T('Customer care coordinator','مسؤول متابعة العملاء')}</b></div><div class="row"><span>${T('Visit','الزيارة')}</span><b>${c.bookingId||T('Prelaunch inquiry','استفسار قبل التشغيل')}</b></div>${c.details?'<div class="row"><span>'+T('Example contact','تواصل تجريبي')+'</span><b>'+C_escape(c.details.name)+'<br>'+C_escape(c.details.contact)+'</b></div>'+(c.details.category?'<div class="row"><span>'+T('Category / availability','الفئة والمواعيد')+'</span><b>'+C_escape(c.details.category)+'<br>'+C_escape(c.details.availability)+'</b></div>':''):''}<ol class="event-list">${c.events.map(e=>'<li>'+T(e.en,e.ar)+'</li>').join('')}</ol>${c.status==='open'?button(T('Simulate team assignment','جرّب تعيين فريق مسؤول'),'data-case-state="assigned"'):c.status==='assigned'?button(T('Simulate an update','جرّب تحديث من الفريق'),'data-case-state="inprogress"'):c.status==='inprogress'?button(T('Simulate resolution','جرّب حل الطلب'),'data-case-state="resolved"'):''}<div class="note">${T('A real team would verify the issue privately, coordinate the permitted action and confirm the outcome. Acknowledgement is not resolution.','الفريق الفعلي يراجع المشكلة بشكل خاص، وينسّق الإجراء المسموح ويتأكد من النتيجة. تأكيد استلام الطلب مش معناه إن المشكلة اتحلّت.')}</div></section>`:''}<div class="case-list">${C_cases.map(x=>`<button data-open-case="${x.id}"><b>${x.id} · ${C_reason(x.reason)}</b><span>${C_caseStatus(x.status)}</span></button>`).join('')||'<div class="panel">'+T('No example cases yet.','لسه مفيش طلبات مساعدة تجريبية.')+'</div>'}</div>${button(T('Create an example inquiry','اعمل استفسار تجريبي'),'data-modal="customer"','')}</main>`;}
function C_reason(r){return ({delay:T('Provider delay','تأخير الدكتور'),unreachable:T('Recipient unreachable','الشخص مش بيرد'),payment:T('Payment / refund follow-up','متابعة الدفع أو الاسترداد'),permission:T('Contact or permission question','سؤال عن التواصل أو الموافقة'),change:T('Changing a visit','تغيير زيارة'),launch:T('Service availability inquiry','استفسار عن إتاحة الخدمة'),provider:T('Partnership inquiry','استفسار شراكة')})[r]||T('Booking support','مساعدة في الحجز');}
function C_caseStatus(s){return ({open:T('Open','مفتوح'),assigned:T('Assigned','اتحدد له مسؤول'),inprogress:T('In progress','جاري المتابعة'),resolved:T('Resolved · simulation','اتحلّ · تجربة')})[s];}
function C_newCase(reason,queue='customer'){const c={id:'CASE-DEMO-'+String(C_cases.length+1).padStart(3,'0'),bookingId:queue==='provider'||reason==='launch'?null:(page==='book'?C_booking()?.id||null:null),reason,queue,status:'open',events:[{en:'Example inquiry received. No message sent.',ar:'استفسار تجريبي اتسجل. مفيش رسالة اتبعتت.'}]};C_cases.push(c);C_case=c.id;return c;}
modal=function(kind){const d=$('#modal');if(kind==='recipient-invitation'){C_invitation(d);return;}if(!['menu','manage','support','customer','provider','video-room','contact-check'].includes(kind))return C_originalModal(kind);let content='';if(kind==='contact-check')content='<h2>'+T('A contact-check preview','تصوّر لمراجعة التواصل')+'</h2><p>'+T('No SMS is sent. Enter the displayed example code 246810 to explore the check, or preview an assisted contact review.','مفيش رسالة بتتبعت. اكتب كود المثال الظاهر 246810 علشان تجرّب المراجعة، أو جرّب مراجعة التواصل بمساعدة.')+'</p><label class="field">'+T('Example code','كود المثال')+'<input id="demoCode" inputmode="numeric" maxlength="6" autocomplete="off" placeholder="246810" dir="ltr"></label><p id="codeError" role="status"></p>'+button(T('Check example code','راجع كود المثال'),'data-check-code')+button(T('Preview assisted contact review','جرّب مراجعة التواصل بمساعدة'),'data-assisted-contact','');else if(kind==='menu')content=`<h2>${T('Where would you like to go?','تحب تروح فين؟')}</h2><div class="menu-links">${[['home',T('Home','الرئيسية')],['care',T('My visits','زياراتي')],['providers',T('For providers','لمقدمي الخدمة')],['help',T('Help & privacy','المساعدة والخصوصية')],['support-cases',T('Support cases','طلبات المساعدة')]].map(([r,n])=>button(n,`data-go="${r}"`,'')).join('')}</div>`;else if(kind==='manage'){const b=C_booking();content=`<h2>${T('Keep your plans clear.','نرتّب التغيير بوضوح.')}</h2><p>${T('Your confirmed visit stays in place while a change is reviewed. A replacement takes effect only after acceptance and any required price adjustment.','الزيارة المؤكدة تفضل زي ما هي وإحنا بنراجع التغيير. البديل يتأكد بعد القبول وأي تسوية مطلوبة لفرق السعر.')}</p>${b?.status==='confirmed'?button(T('Choose another provider or time','اختار دكتور أو معاد تاني'),'data-reschedule'):''}${button(T('Cancel this example visit','الغي الزيارة التجريبية'),'data-status="cancelled"','')}<small>${T('Real cancellation fees and refund timing require approved terms.','رسوم الإلغاء ومدة الاسترداد الفعلية محتاجين شروط معتمدة.')}</small>`;}else if(kind==='video-room')content=`<h2>${T('Joining should feel simple.','الدخول المفروض يبقى سهل.')}</h2><p>${T('The recipient would get a private joining link and a device check. If the connection fails, support helps rejoin or follows the approved reschedule/refund route. No real call, camera or microphone opens here.','الشخص يستلم رابط دخول خاص واختبار للجهاز. لو الاتصال قطع، الدعم يساعده يرجع أو يتبع مسار التغيير أو الاسترداد المعتمد. مفيش مكالمة أو كاميرا أو ميكروفون بيتفتحوا هنا.')}</p>${button(T('Create a connection-help case','اعمل طلب مساعدة للاتصال'),'data-create-case="change"')}`;else{const provider=kind==='provider';content=`<h2>${provider?T('Tell us about your service.','عرّفنا بخدماتك.'):T('What would you like help with?','نساعدك في إيه؟')}</h2><p>${T('Use fictional details. This creates an example case in this tab; it does not contact a team.','استخدم بيانات تجريبية. ده بيسجّل مثال لطلب في التبويب بس، مش بيتواصل مع فريق.')}</p><form id="inquiryForm" data-queue="${provider?'provider':'customer'}"><label class="field">${T('Name · example','الاسم · مثال')}<input name="name" required maxlength="80" placeholder="${T('Demo contact','شخص تجريبي')}" autocomplete="off"></label><label class="field">${T('Contact · example','وسيلة تواصل · مثال')}<input name="contact" required maxlength="80" placeholder="demo@example.com" autocomplete="off"></label>${provider?`<label class="field">${T('Professional category','الفئة المهنية')}<select name="category"><option>${T('Home doctor','دكتور زيارات منزلية')}</option><option>${T('Veterinary','بيطري')}</option><option>${T('Nursing','تمريض')}</option><option>${T('Pharmacy / diagnostics partner','شريك صيدلية أو تحاليل')}</option></select></label><label class="field">${T('Area and available windows · example','المنطقة والمواعيد المتاحة · مثال')}<input name="availability" required maxlength="120" placeholder="${T('North Lotus · Sunday afternoons','اللوتس الشمالية · الأحد بعد الظهر')}"></label>`:`<label class="field">${T('Topic','الموضوع')}<select name="reason">${['launch','delay','unreachable','payment','permission','change'].map(r=>`<option value="${r}">${C_reason(r)}</option>`).join('')}</select></label>`}${button(T('Create example inquiry','سجّل استفسار تجريبي'),'type="submit"')}<small>${T('Production needs a connected helpdesk/CRM and a staffed team. Neither is connected here.','التشغيل الفعلي محتاج نظام متابعة متصل وفريق متاح. الاتنين مش متصلين هنا.')}</small></form>`;}d.innerHTML=button('×','data-close aria-label="'+T('Close','اقفل')+'"','modal-close')+content;if(!d.open)d.showModal();};
const C_oldInformational=informational;
informational=function(){if(page==='support-cases')return C_casePage();return C_oldInformational();};
function C_render(focus=false){const active=document.activeElement;const attrs=['data-who','data-service','data-provider','data-day','data-slot','data-role','data-visit'];const attr=attrs.find(k=>active?.hasAttribute(k));const selector=active?.id?'#'+CSS.escape(active.id):attr?'['+attr+'="'+active.getAttribute(attr)+'"]':null;const opened=[...document.querySelectorAll('#main details[open]')].map(d=>d.querySelector('summary')?.textContent);document.body.dataset.flow=page==='book'&&step<6?'booking':'browse';render(focus);document.querySelectorAll('#app button:not([type])').forEach(b=>b.type='button');if(page==='book'&&step<6){const nav=$('.mobile-nav');if(nav)nav.remove();}for(const detail of document.querySelectorAll('#main details'))if(opened.includes(detail.querySelector('summary')?.textContent))detail.open=true;if(!focus&&selector)document.querySelector(selector)?.focus({preventScroll:true});if(C_error){const e=$('#flowError');e?.focus({preventScroll:true});} }
function C_firstIncomplete(){const phone=(v,egypt=false)=>C_phone(v,egypt);if(!form.bookerName.trim()||!phone(form.bookerPhone,form.country==='eg')||!form.adult||(form.who==='family'&&(!form.recipientName.trim()||!phone(form.recipientPhone,true))))return 0;if(form.area!=='lotus'||!form.street.trim()||!form.building.trim()||(form.contactMode==='other'&&(!form.contactName.trim()||!phone(form.contactPhone,true))))return 1;if(!form.suitable)return 2;if(!form.provider||form.slot===null||!availableDays().includes(form.day))return 3;if(!form.contactVerified||!form.agreement||(form.who==='family'&&form.consentState!=='approved'))return 4;if(!form.ack)return 5;return 6;}
routeChanged=function(){C_error='';C_errorField='';const r=location.hash.slice(1)||'home';if(r.startsWith('visit/')){C_active=r.split('/')[1];page='book';step=6;if(!C_booking()){page='care';step=0;}else{request=C_booking();status=request.status;}}else if(r.startsWith('book/')){page='book';step=Math.max(0,steps.indexOf(r.split('/')[1]));if(step===6){if(C_booking()){request=C_booking();status=request.status;}else{page='care';step=0;}}else{request=null;status='draft';}}else page=['home','care','providers','help','home-visits','video','how','vet','nurse','lab','pharmacy','support-cases'].includes(r)?r:'home';if(page==='book'&&step<6){const incomplete=C_firstIncomplete();if(step>incomplete){step=incomplete;history.replaceState(null,'','#book/'+steps[step]);}}C_render(true);window.scrollTo({top:0,behavior:'instant'});};
start=function(who,service='home'){C_submitting=false;C_editing=null;C_active=null;request=null;status='draft';Object.assign(form,C_defaults(),{who,service});C_draft={data:C_clone(form),step:0,editingId:null};go('book/recipient');};
function C_fail(message,field){C_error=message;C_errorField=field||'';C_render();if(field)document.getElementById(field)?.focus();else $('#flowError')?.scrollIntoView({block:'center',behavior:'instant'});return false;}
function C_validate(){C_clearError();const phone=(v,egypt=false)=>C_phone(v,egypt);if(step===0){for(const key of ['bookerName','bookerPhone',...(form.who==='family'?['recipientName','recipientPhone']:[])]){if(!String(form[key]).trim())return C_fail(T('Please complete the name and contact fields, or use the example details.','كمّل الاسم وبيانات التواصل، أو استخدم بيانات المثال.'),key);if(key.endsWith('Phone')&&!phone(form[key],key!=='bookerPhone'||form.country==='eg'))return C_fail(key==='bookerPhone'?form.country==='eg'?T('Enter an Egyptian mobile number, starting with 01 or +20.','اكتب رقم موبايل مصري يبدأ بـ01 أو +20.'):T('Add a country code, then 8–15 digits, for example +1 202 555 0146.','اكتب كود البلد وبعده من ٨ لـ١٥ رقم، زي +1 202 555 0146.'):T('Enter an Egyptian mobile number, for example 01000000000 or +20 10 0000 0000.','اكتب رقم موبايل مصري، زي 01000000000 أو +20 10 0000 0000.'),key);}if(!form.adult)return C_fail(T('This first offer is for adults. Confirm the adult example to continue.','العرض الأول للكبار. أكّد إن المثال لشخص بالغ علشان تكمّل.'),'adult');}if(step===1){if(form.area!=='lotus')return C_fail(T('Choose a supported example area before continuing.','اختار نطاق متاح في المثال علشان تكمّل.'),'area');for(const key of ['street','building',...(form.contactMode==='other'?['contactName','contactPhone']:[])])if(!String(form[key]).trim())return C_fail(T('Complete the address and local contact details.','كمّل العنوان وبيانات الشخص القريب.'),key);if(form.contactMode==='other'&&!phone(form.contactPhone,true))return C_fail(T('Check the example local contact number.','راجع رقم التواصل المحلي التجريبي.'),'contactPhone');}if(step===2&&!form.suitable)return C_fail(T('Confirm this is a planned, non-emergency adult example. A professional still reviews suitability.','أكّد إن المثال لشخص بالغ وحالة غير طارئة بميعاد. المختص لسه لازم يراجع المناسبة.'),'suitable');if(step===3){if(!form.provider||form.slot===null||!availableDays().includes(form.day))return C_fail(T('Choose a professional, an available example date and a time window.','اختار دكتور ويوم متاح في المثال وفترة زيارة.'));if(C_editing){const old=C_bookings.find(b=>b.id===C_editing)?.data;if(old&&old.provider===form.provider&&old.day===form.day&&old.slot===form.slot)return C_fail(T('Choose a different provider or window, or keep the original visit.','اختار دكتور أو فترة مختلفة، أو خلّي الزيارة الأصلية.'));}}if(step===4&&!form.contactVerified)return C_fail(T('Preview a contact check before confirming agreement.','جرّب مراجعة التواصل قبل تأكيد الموافقة.'));if(step===4&&(!form.agreement||(form.who==='family'&&form.consentState!=='approved')))return C_fail(T('Complete the recipient agreement preview before continuing.','كمّل تصوّر موافقة الشخص قبل ما تكمّل.'));if(step===5&&!form.ack)return C_fail(T('Acknowledge the demo before sending the example request.','أكّد إنك فاهم إنها تجربة قبل إرسال الطلب.'),'ack');return true;}
function C_submit(){if(C_submitting)return;C_submitting=true;if(C_editing){const b=C_bookings.find(x=>x.id===C_editing);b.change={state:'pending',data:C_clone(form)};C_event(b,'Change requested; original visit retained.','اتطلب تغيير؛ الزيارة الأصلية اتاحتفظ بيها.');C_active=b.id;C_editing=null;}else{const b={id:'CD-DEMO-'+String(C_bookings.length+1).padStart(3,'0'),data:C_clone(form),status:'pending',payment:'hold',visit:'scheduled',change:null,events:[]};C_event(b,'Request created; awaiting provider.','الطلب اتسجل؛ مستني قبول الدكتور.');C_bookings.push(b);C_active=b.id;}C_draft=null;go('visit/'+C_active);}
function C_transition(next){const b=C_booking();if(!b)return;const allowed={pending:['accepted','declined','expired','cancelled'],accepted:['confirmed','paymentfailed','cancelled'],paymentfailed:['confirmed','paymentfailed','cancelled'],confirmed:['complete','cancelled']};if(!allowed[b.status]?.includes(next))return;b.status=next;if(next==='confirmed')b.payment='captured';if(['declined','expired'].includes(next))b.payment='released';if(next==='cancelled'){b.payment=b.payment==='captured'?'refundpending':'released';b.change=null;if(C_editing===b.id){C_editing=null;C_draft=null;}}if(next==='complete')b.visit='completed';const labels=C_bilingual(()=>C_statusLabel(next));C_event(b,labels.en,labels.ar);status=next;request=b;C_render(true);}
function C_beginChange(){C_submitting=false;const b=C_booking();if(!b||b.status!=='confirmed')return;C_editing=b.id;Object.assign(form,C_clone(b.change?.data||b.data),{agreement:false,consentState:'pending',ack:false});b.change={state:'draft',data:C_clone(form)};C_draft={data:C_clone(form),step:3,editingId:b.id};go('book/provider');}
function C_change(action){const b=C_booking();if(!b?.change)return;if(action==='accept'&&b.change.state==='pending'){b.change.state='accepted';C_event(b,'Change accepted; price adjustment pending.','التغيير اتقبل؛ تسوية فرق السعر معلّقة.');}else if(action==='confirm'&&b.change.state==='accepted'){b.previous=b.previous||[];b.previous.push(C_clone(b.data));b.data=C_clone(b.change.data);b.change=null;b.visit='scheduled';C_event(b,'Change completed. Replacement is now confirmed.','التغيير اكتمل. الزيارة البديلة اتأكدت.');}else if(['decline','discard'].includes(action)){b.change=null;C_event(b,'Original visit retained; proposed change closed.','الزيارة الأصلية اتاحتفظ بيها؛ التغيير المقترح اتقفل.');C_editing=null;C_draft=null;}C_render(true);}
function C_fill(){C_clearError();form.contactVerified=false;form.agreement=false;form.consentState='pending';form.updates=false;form.bookerName=lang==='ar'?'عمر تجريبي':'Omar Demo';form.bookerPhone=form.country==='eg'?'+20 10 0000 0002':'+1 202 555 0146';form.recipientName=({mother:lang==='ar'?'منى تجريبية':'Mona Demo',father:lang==='ar'?'حسن تجريبي':'Hassan Demo',relative:lang==='ar'?'نور تجريبي':'Nour Demo'})[form.relation];form.recipientPhone='+20 10 0000 0000';form.street=lang==='ar'?'شارع تجريبي، اللوتس الشمالية':'Example Street, North Lotus';form.building=lang==='ar'?'عمارة أ · شقة ٢':'Building A · apartment 2';form.floor=lang==='ar'?'الدور التاني':'Second floor';form.access=lang==='ar'?'المدخل الرئيسي · فيه أسانسير':'Main entrance · lift available';form.contactName=lang==='ar'?'ليلى تجريبية':'Layla Demo';form.contactPhone='+20 10 0000 0001';C_saveDraft();C_render();}
document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.field)return;form[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;C_clearError(el.dataset.field);if(['bookerName','bookerPhone','recipientName','recipientPhone'].includes(el.dataset.field)){form.contactVerified=false;form.agreement=false;form.consentState='pending';}if(['street','building','floor','access','contactName','contactPhone'].includes(el.dataset.field)){form.agreement=false;form.consentState='pending';form.updates=false;}C_saveDraft();});
document.addEventListener('change',e=>{const el=e.target;C_clearError(el.dataset.field);if(el.id==='visitDate'){form.slot=null;if(el.value)form.day=Math.round((new Date(el.value+'T12:00:00Z')-new Date(dateISO(0)+'T12:00:00Z'))/86400000);C_saveDraft();C_render();return;}if(!el.dataset.field)return;form[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;if(['relation','consentMethod','contactMode'].includes(el.dataset.field)){form.consentState='pending';form.agreement=false;form.updates=false;}C_saveDraft();if(['relation','country','area','contactMode','consentMethod'].includes(el.dataset.field))C_render();});
document.addEventListener('submit',e=>{if(e.target.id==='familyStep'){e.preventDefault();if(C_validate()){C_saveDraft();if(step===5)C_submit();else go('book/'+steps[step+1]);}}if(e.target.id==='inquiryForm'){e.preventDefault();const f=e.target;if(!f.reportValidity())return;const provider=f.dataset.queue==='provider';const created=C_newCase(provider?'provider':f.elements.reason.value,provider?'provider':'customer');created.details={name:f.elements.name.value,contact:f.elements.contact.value,category:provider?f.elements.category.value:'',availability:provider?f.elements.availability.value:''};$('#modal').close();go('support-cases');}});
document.addEventListener('click',e=>{const arrange=e.target.closest('a[href="#book/recipient"]');if(arrange){e.preventDefault();if(C_draft){C_submitting=false;C_editing=C_draft.editingId;Object.assign(form,C_clone(C_draft.data));go('book/'+steps[C_draft.step]);}else start('family');return;}const a=e.target.closest('a.skip');if(a){e.preventDefault();$('#main').tabIndex=-1;$('#main').focus();return;}const b=e.target.closest('button,[data-modal]');if(!b)return;if(b.tagName==='BUTTON'&&b.getAttribute('type')!=='submit')e.preventDefault();if(b.hasAttribute('data-close')){$('#modal').close();return;}if(b.dataset.modal){e.preventDefault();modal(b.dataset.modal);return;}if(b.dataset.go){if($('#modal').open)$('#modal').close();go(b.dataset.go);return;}if(b.dataset.start){start(b.dataset.start,b.dataset.startService||'home');return;}if(b.hasAttribute('data-lang')){lang=lang==='en'?'ar':'en';C_render();return;}if(b.hasAttribute('data-invitation')){if(!form.contactVerified){C_fail(T('Check their contact number before opening the invitation.','راجع رقم التواصل معاهم قبل ما تفتح الدعوة.'));return;}modal('recipient-invitation');return;}if(b.hasAttribute('data-verify-contact')){C_clearError();modal('contact-check');return;}if(b.hasAttribute('data-check-code')){if($('#demoCode').value!=='246810'){$('#codeError').textContent=T('Use the displayed example code: 246810.','استخدم كود المثال الظاهر: 246810.');return;}form.contactVerified=true;$('#modal').close();C_saveDraft();C_render();return;}if(b.hasAttribute('data-assisted-contact')){form.contactVerified=true;form.consentMethod='assisted';$('#modal').close();C_saveDraft();C_render();return;}if(b.hasAttribute('data-sample')){C_fill();return;}if(b.hasAttribute('data-next')){$('#familyStep').requestSubmit();return;}if(b.hasAttribute('data-back')){if(step===6){go('care');return;}C_saveDraft();go(step>0?'book/'+steps[step-1]:'care');return;}for(const [attr,key] of [['who','who'],['service','service'],['provider','provider'],['day','day'],['slot','slot']])if(b.dataset[attr]!==undefined){C_clearError();form[key]=['provider','day','slot'].includes(key)?Number(b.dataset[attr]):b.dataset[attr];if(key==='who')form.contactVerified=false;if(['service','provider','day'].includes(key))form.slot=null;if(['who','service','provider','day','slot'].includes(key)){form.agreement=false;form.consentState='pending';form.updates=false;}C_saveDraft();C_render();return;}if(b.dataset.consent){if(!form.contactVerified){C_fail(T('Check the example recipient contact first.','راجع وسيلة التواصل التجريبية الأول.'));return;}const share=document.getElementById('recipientShare')?.checked||false;form.consentState=b.dataset.consent;form.agreement=false;form.updates=b.dataset.consent==='approved'&&share;if($('#modal').open)$('#modal').close();C_clearError();C_saveDraft();C_render();return;}if(b.dataset.openBooking){C_active=b.dataset.openBooking;C_view='booker';go('visit/'+C_active);return;}if(b.hasAttribute('data-resume')){if(C_draft){C_editing=C_draft.editingId;Object.assign(form,C_clone(C_draft.data));go('book/'+steps[C_draft.step]);}return;}if(b.hasAttribute('data-reschedule')||b.hasAttribute('data-resume-change')){if($('#modal').open)$('#modal').close();C_beginChange();return;}if(b.dataset.change){C_change(b.dataset.change);return;}if(b.dataset.status){if($('#modal').open)$('#modal').close();C_transition(b.dataset.status);return;}if(b.dataset.role){C_view=b.dataset.role;C_render();return;}if(b.dataset.visit){const rec=C_booking();if(rec){rec.visit=b.dataset.visit;C_event(rec,'Visit state: '+b.dataset.visit,'تحديث حالة الزيارة: '+({travelling:'في الطريق',delayed:'تأخير',arrived:'وصل'})[b.dataset.visit]);C_render();}return;}if(b.hasAttribute('data-unreachable')||b.dataset.createCase){C_newCase(b.dataset.createCase||'unreachable');if($('#modal').open)$('#modal').close();go('support-cases');return;}if(b.dataset.openCase){C_case=b.dataset.openCase;go('support-cases');return;}if(b.dataset.caseState){const c=C_cases.find(x=>x.id===C_case);if(c){c.status=b.dataset.caseState;c.events.push(C_bilingual(()=>C_caseStatus(c.status)));C_render();}return;}if(b.hasAttribute('data-refund')){const rec=C_booking();if(rec?.payment==='refundpending'){rec.payment='refunded';C_event(rec,'Simulated refund complete.','الاسترداد التجريبي اكتمل.');C_render();}return;}if(b.hasAttribute('data-retry')){C_submitting=false;const rec=C_booking();if(rec){C_editing=null;Object.assign(form,C_clone(rec.data),{provider:0,slot:null,agreement:false,consentState:'pending',ack:false});C_draft={data:C_clone(form),step:3,editingId:null};go('book/provider');}return;}if(b.dataset.story!==undefined){storyStage=Number(b.dataset.story);$('#storyScene').innerHTML=scenario();$('#storyScene [data-story="'+storyStage+'"]').focus({preventScroll:true});return;}if(b.hasAttribute('data-dismiss-app')){b.closest('.app-nudge').remove();try{sessionStorage.setItem('casa-home-app-nudge','dismissed');}catch{}return;}});

function C_invitation(d){const assisted=form.consentMethod!=='recipient';d.innerHTML=button('×','data-close aria-label="'+T('Close','اقفل')+'"','modal-close')+'<section class="recipient-invitation"><span class="badge">'+T('Recipient experience · example invitation','تجربة اللي هيستقبل الزيارة · دعوة تجريبية')+'</span><div class="invitation-emblem">'+icon(form.service==='home'?'home':'video')+'</div><h2>'+T('A visit, arranged with you.','زيارة على راحتك وبموافقتك.')+'</h2><p>'+C_escape(form.bookerName)+' '+T('would like to arrange care for you. Review the details before you decide.','حابب يرتّب لك رعاية. شوف التفاصيل الأول، والقرار ليك.')+'</p><div class="invitation-details recipient-facts"><div>'+icon('person')+'<div><small>'+T('Your doctor · fictional profile','الدكتور · بيانات تجريبية')+'</small><b>'+C_escape(lang==='ar'?provider().ar:provider().en)+'</b></div></div><div>'+icon('clock')+'<div><small>'+T('Egypt time','بتوقيت مصر')+'</small><b>'+new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{timeZone:'Africa/Cairo',weekday:'short',day:'numeric',month:'short'}).format(serviceDate())+'<br><span class="recipient-clock">'+C_slot(form.slot)+'</span></b><small>'+windowLabel()+'</small></div></div><div>'+icon('pin')+'<div><small>'+T('Your address','عنوانك')+'</small><b>'+address()+'</b></div></div></div><details class="quiet-details"><summary>'+T('Service and example fee','الخدمة والسعر التجريبي')+'</summary><p>'+serviceName()+' · '+money(C_price(form))+'</p></details>'+(assisted?'<div class="note">'+(form.consentMethod==='assisted'?T('A support colleague would explain the visit, hear the recipient’s decision and record it. No call is made here.','حد من الدعم يوضّح تفاصيل الزيارة، يسمع قرار اللي هيستقبلها ويسجّله. مفيش مكالمة بتتعمل هنا.'):T('A private review must establish the representative’s authority. Family relationship or payment alone is not authorization. No document is verified here.','لازم التفويض يتراجع بشكل خاص. القرابة أو دفع الفلوس لوحدهم مش تفويض. مفيش مستند بيتراجع هنا.'))+'</div>':'')+'<label class="check"><input id="recipientShare" type="checkbox" '+(form.updates?'checked':'')+'><span>'+T('Share booking updates with the person arranging this visit.','موافق إن تحديثات الحجز توصل للي بيرتّب الزيارة.')+'<small>'+T('Optional. No diagnosis, prescription or medical notes are shared.','اختياري. من غير تشخيص أو روشتة أو ملاحظات طبية.')+'</small></span></label><div class="status-actions">'+button(assisted?T('Simulate reviewed agreement','جرّب تسجيل الموافقة بعد المراجعة'):T('Agree to these details · demo','موافق على التفاصيل دي · تجربة'),'data-consent="approved"')+button(T('This does not suit me · demo','الترتيب ده مش مناسب ليا · تجربة'),'data-consent="declined"','')+'</div><small>'+T('Prototype only: this preview sends no invitation, verifies no identity and creates no confirmed appointment.','للتجربة بس: الدعوة مش بتتبعت، ومفيش تحقق من الهوية أو حجز مؤكد. ابدأ بمراجعة التفاصيل، وبعدها القبول والدفع.')+'</small></section>';if(!d.open)d.showModal();}

window.addEventListener('hashchange',routeChanged);routeChanged();
